"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["71338"],{69459(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_distribuicao_vagas.modalidade_do_rol_ausente","status":422,"titulo":"Falta modalidade do rol fechado que a regra de distribui\xe7\xe3o exige"},"descricao":{"codigo":"uniplus.selecao.configuracao_distribuicao_vagas.modalidade_do_rol_ausente","requisitos":["UNI-REQ-0140"],"oQueAconteceu":["A regra de distribui\xe7\xe3o de vagas referenciada declara um rol fechado de\\nmodalidades, e a oferta n\xe3o selecionou todas as modalidades desse rol. Rol\\nfechado exige igualdade exata com a sele\xe7\xe3o da oferta \u2014 faltar uma\\nmodalidade do rol \xe9 recusado do mesmo jeito que sobrar uma modalidade fora\\ndele\\n([`modalidade_nao_admitida_pela_regra`](/erros/uniplus.selecao.configuracao_distribuicao_vagas.modalidade_nao_admitida_pela_regra)).\\nA regra **determina** o conjunto inteiro; n\xe3o h\xe1 modalidade do rol que seja\\nopcional.","`DISTRIB-VAGAS-INSTITUCIONAL` \xe9 a \xfanica regra de rol aberto e n\xe3o emite este\\nerro. Nas quatro regras de rol fechado, a mensagem nomeia, dinamicamente, as\\nmodalidades que faltam \u2014 por exemplo, selecionar as nove modalidades da Lei\\n12.711 pura sob `DISTRIB-VAGAS-LEI-12711-COM-AC-PCD` falta `AC_PCD`, a\\nd\xe9cima modalidade que s\xf3 essa varia\xe7\xe3o exige."],"comoResolver":["Complete a sele\xe7\xe3o com todas as modalidades que o rol da regra escolhida\\nexige. Se a oferta n\xe3o deveria ter todas essas modalidades, a regra de\\ndistribui\xe7\xe3o est\xe1 errada para o caso \u2014 reveja qual das cinco regras\\ncorresponde ao que a oferta realmente pretende."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao distribuicao vagas"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);